export const COURSE_LOGISTICS_BY_NAME = Object.fromEntries(
  COURSE_LOGISTICS_LIST.map((entry) => [entry.name, entry])
)

export function getCourseLogisticsByName(name) {
  if (!name) return null
  if (COURSE_LOGISTICS_BY_NAME[name]) return COURSE_LOGISTICS_BY_NAME[name]
  const resolved = resolveCourseAccessName(name)
  return resolved ? COURSE_LOGISTICS_BY_NAME[resolved] || null : null
}

// Buggy hire is a flat per-round fee, not a seasonal range. Show the master
// price, or 'Included' where the day-cost figure already bundles it.
export function formatBuggyPrice(entryOrName) {
  const entry =
    typeof entryOrName === 'string' ? getCourseLogisticsByName(entryOrName) : entryOrName
  if (!entry) return null
  if (entry.buggyIncl) return 'Included'
  return Number.isFinite(entry.buggy) && entry.buggy > 0 ? `\u20ac${entry.buggy}` : null
}
